package main

import (
	"math"
)

// ==================================================
// Phase D: GPT 모델 구조 (Go 구현)
// ==================================================

// 텐서 (1D 평탄화)
type Tensor struct {
	data   []float64
	shape  []int
	size   int
}

// 파라미터 (requires_grad 포함)
type Parameter struct {
	data  *Tensor
	grad  *Tensor
}

// 선형 레이어
type Linear struct {
	weight *Parameter
	bias   *Parameter
	in     int
	out    int
}

// 레이어 정규화
type LayerNorm struct {
	weight *Parameter
	bias   *Parameter
	eps    float64
}

// GPT 설정
type GPTConfig struct {
	VocabSize int
	DModel    int
	NumHeads  int
	NumLayers int
	MaxSeqLen int
}

// ==================================================
// 유틸리티
// ==================================================

// 텐서 생성
func NewTensor(shape []int) *Tensor {
	size := 1
	for _, d := range shape {
		size *= d
	}
	return &Tensor{
		data:  make([]float64, size),
		shape: shape,
		size:  size,
	}
}

// 랜덤 초기화 (Xavier)
func (t *Tensor) InitXavier(in, out int) {
	scale := math.Sqrt(2.0 / float64(in+out))
	for i := range t.data {
		// 단순 균등분포 (정규분포는 생략)
		t.data[i] = (math.Sin(float64(i*17%1000)) * scale) - scale/2
	}
}

// 인덱스 접근 (2D)
func (t *Tensor) Get(i, j int) float64 {
	idx := i*t.shape[1] + j
	if idx < len(t.data) {
		return t.data[idx]
	}
	return 0

