import (
	"fmt"
	"os"
)

// ==================================================
// FreeLang GPT - Training Driver
// Priority 2 (SGD): 안정적인 기준선
// Priority 3 (Adam): hybrid 구현
// ==================================================

func main() {
	mode := "priority2"

	// 커맨드라인 인자로 모드 선택
	// Termux 환경: Args[1]이 절대경로로 주입되는 경우가 있어 '/'로 시작하지 않는 인자를 사용
	for i := 1; i < len(os.Args); i++ {
		arg := os.Args[i]
		if len(arg) > 0 && arg[0] != '/' {
			mode = arg
			break
		}
	}

	switch mode {
	case "priority2":
		trainWithRealLoss()

	case "priority3":
		testAdamOptimizer()
		fmt.Println("")
		fmt.Println("🔄 Starting Priority 3 training with Adam...")
		fmt.Println("")
		trainWithAdam()

	case "test-optimizer":
		TestOptimizers()

	case "validate-adam":
		testAdamOptimizer()

	case "collect-md":
		testMDCollection()

	case "phase4":
		trainWithAttention()

	case "phase5":
		trainTransformer()

	case "phase6":
		trainTransformerV2()

	case "phase7":
		trainBP()

	case "phase7s":
		trainBPServer()

