import (
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strings"
)

// ==================================================
// BPE Tokenizer (Byte-Pair Encoding)
//
// 학습: 텍스트 → 빈도 기반 머지 → vocab
// 인코딩: 텍스트 → []int
// 디코딩: []int → 텍스트
// ==================================================

type BPETokenizer struct {
	Vocab   map[string]int // token → id
	RevVocab map[int]string // id → token
	Merges  []BPEMerge     // 머지 규칙 (순서 중요)
}

type BPEMerge struct {
	A, B   string
	Result string
}

type BPEConfig struct {
	Vocab   map[string]int `json:"vocab"`
	Merges  [][]string     `json:"merges"` // [[a, b], ...]
}

// ─────────────────────────────────────────────────
// 학습
// ─────────────────────────────────────────────────

func TrainBPE(text string, vocabSize int) *BPETokenizer {
	fmt.Printf("[BPE] 학습 시작: 목표 vocab=%d\n", vocabSize)

	// 1) 초기 vocab: 모든 바이트(문자) + 특수 토큰
	baseVocab := map[string]int{}
	baseVocab["<UNK>"] = 0
	baseVocab["<PAD>"] = 1
	baseVocab["<BOS>"] = 2
	baseVocab["<EOS>"] = 3
	nextID := 4

	for _, ch := range text {
		s := string(ch)
		if _, ok := baseVocab[s]; !ok {
			baseVocab[s] = nextID
			nextID++
		}
	}
	fmt.Printf("[BPE] 초기 문자 vocab: %d\n", len(baseVocab))

	// 2) 단어 분리 (공백 기준, 각 문자 사이 공백)
	words := tokenizeWords(text)

