	samples := []GeneratedSample{}

	testCases := []struct {
		prompt string
		temp   float64
		topK   int
	}{
		{"fn", 0.7, 5},
		{"fn", 1.0, 10},
		{"let", 0.7, 5},
		{"let", 1.0, 10},
		{"//", 0.8, 8},
		{"FreeLang", 0.7, 5},
		{"Phase", 0.9, 8},
		{"return", 0.7, 5},
	}

	for _, tc := range testCases {
		text := generatePhaseI(model, corpus, tc.prompt, 20, tc.temp, tc.topK)
		samples = append(samples, GeneratedSample{
			Prompt: tc.prompt,
			Text:   text,
			Temp:   tc.temp,
			TopK:   tc.topK,
		})
