	fmt.Printf("║  VocabSize: %d                                           ║\n", corpus.vocabSize)
	fmt.Printf("║  Params:   ~%dk                                          ║\n", params/1000)
	fmt.Printf("╚══════════════════════════════════════════════════════════════╝\n")

	return result
}

