// ==================================================
// Phase I: 평가 모듈
//
// - loadPhaseIModel: 저장된 Phase I 모델 로드
// - evalPhaseI: vocab + 모델 로드 후 평가
// - PhaseIResult: 평가 결과 구조체
// ==================================================

// 평가 결과
type PhaseIResult struct {
	ValPPL    float64
	Samples   []GeneratedSample
	VocabSize int
	Params    int
}

type GeneratedSample struct {
	Prompt   string
	Text     string
	Temp     float64
	TopK     int
}

// ─────────────────────────────────────────────────
// evalPhaseI: 저장된 모델 로드 후 평가
// ─────────────────────────────────────────────────

func evalPhaseI() *PhaseIResult {
	fmt.Println("\n╔══════════════════════════════════════════════════════════════╗")
	fmt.Println("║  FreeLang GPT — Phase I: 모델 평가                         ║")
	fmt.Println("╚══════════════════════════════════════════════════════════════╝\n")

	// 코퍼스 로드
	fmt.Print("[1/3] 코퍼스 로드... ")
	corpus, err := loadPhaseICorpus("data/real_corpus.txt", 500_000)
	if err != nil {
		corpus, err = loadPhaseICorpus("data/real_corpus_large.txt", 300_000)
		if err != nil {
			fmt.Printf("❌ %v\n", err)
			return nil
		}
	}
	fmt.Printf("✅ vocab=%d tokens=%d\n", corpus.vocabSize, len(corpus.tokens))

	// 모델 로드
	fmt.Print("[2/3] 모델 로드... ")
	modelPath := "data/phase_i_model.bin"
	if _, err2 := os.Stat(modelPath); os.IsNotExist(err2) {
		fmt.Printf("❌ %s 없음 (먼저 phase_i 실행)\n", modelPath)
		return nil
	}

	model, err := loadNLModel(modelPath)
	if err != nil {
		fmt.Printf("❌ %v\n", err)
		return nil
	}
	fmt.Printf("✅ d=%d layers=%d\n", model.dModel, model.numLayers)

	// Perplexity 계산
	fmt.Print("[3/3] Perplexity 계산... ")
	splitIdx    := len(corpus.tokens) * 9 / 10
	valTokens   := corpus.tokens[splitIdx:]
	valPPL      := calcPerplexity(model, valTokens, 32, 200)
	fmt.Printf("✅ valPPL=%.2f\n\n", valPPL)

	// 텍스트 생성
	fmt.Println("═══ 텍스트 생성 평가 ═══════════════════════════════════════════")
	samples := []GeneratedSample{}

	testCases := []struct {
		prompt string
		temp   float64
		topK   int
	}{
		{"fn", 0.7, 5},
		{"fn", 1.0, 10},
		{"let", 0.7, 5},
		{"let", 1.0, 10},
		{"//", 0.8, 8},
		{"FreeLang", 0.7, 5},
		{"Phase", 0.9, 8},
		{"return", 0.7, 5},
	}

	for _, tc := range testCases {
		text := generatePhaseI(model, corpus, tc.prompt, 20, tc.temp, tc.topK)
		samples = append(samples, GeneratedSample{
			Prompt: tc.prompt,
			Text:   text,
			Temp:   tc.temp,
			TopK:   tc.topK,
		})
		fmt.Printf("  \"%s\" (t=%.1f k=%d): %s %s\n",
			tc.prompt, tc.temp, tc.topK, tc.prompt, text)
	}

	params := model.vocabSize*model.dModel +
		model.numLayers*(4*model.dModel*model.dModel+2*model.dModel*model.dFFn) +
		model.dModel*model.vocabSize

	result := &PhaseIResult{
		ValPPL:    valPPL,
		Samples:   samples,
		VocabSize: corpus.vocabSize,
		Params:    params,
	}

	// 요약
	fmt.Printf("\n╔══════════════════════════════════════════════════════════════╗\n")
	fmt.Printf("║  평가 결과 요약                                             ║\n")
	fmt.Printf("║  ValPPL:   %.2f                                           ║\n", valPPL)
	fmt.Printf("║  VocabSize: %d                                           ║\n", corpus.vocabSize)
	fmt.Printf("║  Params:   ~%dk                                          ║\n", params/1000)
	fmt.Printf("╚══════════════════════════════════════════════════════════════╝\n")

	return result
}


// ─────────────────────────────────────────────────
// Fluency 점수: 생성된 텍스트의 단어 다양성
// ─────────────────────────────────────────────────

func fluencyScore(samples []GeneratedSample) float64 {
	allWords := map[string]bool{}
	total := 0
	for _, s := range samples {
		words := strings.Fields(s.Text)
		for _, w := range words {
			allWords[w] = true
			total++
		}
	}
	if total == 0 {
		return 0
	}
	return float64(len(allWords)) / float64(total)
}

// ─────────────────────────────────────────────────
// evalPhaseIReport: 텍스트 보고서 생성
// ─────────────────────────────────────────────────

func evalPhaseIReport(r *PhaseIResult) string {
	if r == nil {
		return "평가 실패"
	}

	var sb strings.Builder
	sb.WriteString("# FreeLang GPT Phase I — 평가 보고서\n\n")
	sb.WriteString(fmt.Sprintf("- 검증 Perplexity: **%.2f**\n", r.ValPPL))
	sb.WriteString(fmt.Sprintf("- 어휘 크기: %d\n", r.VocabSize))
	sb.WriteString(fmt.Sprintf("- 파라미터: ~%dk\n", r.Params/1000))

	fluency := fluencyScore(r.Samples)
	sb.WriteString(fmt.Sprintf("- 유창성 점수: %.3f\n\n", fluency))

	sb.WriteString("## 생성 샘플\n\n")
	for _, s := range r.Samples {
		sb.WriteString(fmt.Sprintf("**`%s`** (temp=%.1f, k=%d): %s %s\n\n",
			s.Prompt, s.Temp, s.TopK, s.Prompt, s.Text))
	}

	// 등급 판정
	grade := "F"
	switch {
	case r.ValPPL < 50:
		grade = "A"
	case r.ValPPL < 100:
		grade = "B"
	case r.ValPPL < 200:
		grade = "C"
	case r.ValPPL < 500:
		grade = "D"
	default:
		grade = "F"
	}

	sb.WriteString(fmt.Sprintf("\n## 종합 등급: **%s** (PPL=%.2f)\n", grade, r.ValPPL))
	return sb.String()
}

// ─────────────────────────────────────────────────
// NLayerModel 파일 로드 (transformer_nlayer.go에 있는 함수 위임)
// ─────────────────────────────────────────────────

func loadNLModelFromFile(path string) (*NLayerModel, error) {
	return loadNLModel(path)
}

// ─────────────────────────────────────────────────
// 토큰 시퀀스 → 텍스트 (디코딩)
// ─────────────────────────────────────────────────

func decodeTokens(tokens []int, revVocab map[int]string) string {
	words := make([]string, 0, len(tokens))
	for _, id := range tokens {
		if w, ok := revVocab[id]; ok {
			words = append(words, w)
		} else {
			words = append(words, "<UNK>")
		}
	}
	return strings.Join(words, " ")
}

// ─────────────────────────────────────────────────
// 비교 평가: nl_model.bin (Phase 8) vs phase_i_model.bin
// ─────────────────────────────────────────────────

func compareModels() {
	fmt.Println("\n╔══════════════════════════════════════════════════════════════╗")
	fmt.Println("║  모델 비교: Phase 8 vs Phase I                              ║")
	fmt.Println("╚══════════════════════════════════════════════════════════════╝\n")

	corpus, err := loadPhaseICorpus("data/real_corpus.txt", 200_000)
	if err != nil {
		corpus, err = loadPhaseICorpus("data/real_corpus_large.txt", 200_000)
		if err != nil {
			fmt.Printf("❌ corpus: %v\n", err)
			return
		}
	}

	splitIdx  := len(corpus.tokens) * 9 / 10
	valTokens := corpus.tokens[splitIdx:]

	models := []struct {
		name string
		path string
	}{
		{"Phase 8", "data/nl_model.bin"},
		{"Phase I", "data/phase_i_model.bin"},
	}

	fmt.Printf("%-10s %10s %12s\n", "모델", "ValPPL", "파라미터")
	fmt.Println(strings.Repeat("─", 35))

	for _, m := range models {
		if _, err2 := os.Stat(m.path); os.IsNotExist(err2) {
			fmt.Printf("%-10s %10s\n", m.name, "N/A")
			continue
		}
		model, err2 := loadNLModelFromFile(m.path)
		if err2 != nil {
			fmt.Printf("%-10s %10s (%v)\n", m.name, "ERR", err2)
			continue
		}
		valPPL := calcPerplexity(model, valTokens, 32, 100)
		params := model.vocabSize*model.dModel +
			model.numLayers*(4*model.dModel*model.dModel+2*model.dModel*model.dFFn) +
			model.dModel*model.vocabSize
		fmt.Printf("%-10s %10.2f %12dk\n", m.name, valPPL, params/1000)
	}

	// Perplexity 개선률 계산
	fmt.Println()
	if _, err2 := os.Stat("data/nl_model.bin"); !os.IsNotExist(err2) {
		if _, err3 := os.Stat("data/phase_i_model.bin"); !os.IsNotExist(err3) {
			m8, e8 := loadNLModelFromFile("data/nl_model.bin")
			mi, ei := loadNLModelFromFile("data/phase_i_model.bin")
			if e8 == nil && ei == nil {
				ppl8 := calcPerplexity(m8, valTokens, 32, 100)
				pplI := calcPerplexity(mi, valTokens, 32, 100)
				impr := (ppl8 - pplI) / ppl8 * 100
				if impr > 0 {
					fmt.Printf("✅ Phase I 개선: %.1f%% (%.2f → %.2f)\n", impr, ppl8, pplI)
				} else {
					fmt.Printf("⚠️  Phase 8이 더 낮음: %.2f vs %.2f\n", ppl8, pplI)
				}
			}
		}
	}

	_ = math.Pi // suppress import
}

