package main

import (
	"encoding/json"
	"fmt"
	"math"
	"math/rand"
	"net/http"
	"os"
	"strings"
)

// ==================================================
// Phase I API: /api/v2/generate
//
// 엔드포인트:
//   GET  /api/v2/status     — Phase I 모델 상태
//   POST /api/v2/generate   — Top-K + Temperature 생성
//   GET  /api/v2/sample     — 랜덤 샘플 생성
//   POST /api/v2/perplexity — 텍스트 Perplexity 계산
// ==================================================

// ─────────────────────────────────────────────────
// 공유 상태 (서버 시작 시 로드)
// ─────────────────────────────────────────────────

type PhaseIServer struct {
	model     *PhaseINLModel
	corpus    *PhaseIServerCorpus
	modelPath string
	loaded    bool
}

// 서버용 경량 모델 래퍼 (실제 NLayerModel 없이 API 응답만)
type PhaseINLModel struct {
	VocabSize int
	DModel    int
	NumLayers int
	NumHeads  int
	DFFn      int
	Params    int
}

type PhaseIServerCorpus struct {
	VocabSize int
