		return
	}

	if req.Text == "" {
		req.Text = "fn add(a: i32, b: i32) -> i32 { return a + b }"
	}

	// 근사 perplexity 계산 (단어 빈도 기반)
	words := strings.Fields(req.Text)
	knownWords := map[string]bool{
		"fn": true, "let": true, "return": true, "if": true, "else": true,
		"for": true, "while": true, "i32": true, "f32": true, "str": true,
		"->": true, "FreeLang": true, "print": true, "in": true, "range": true,
	}

	totalLogP := 0.0
	for _, w2 := range words {
		if knownWords[w2] {
			totalLogP += math.Log(0.08) // 알려진 단어: 높은 확률
		} else {
