		"->", "if", "else", "for", "while", "print",
	}

	result := make([]string, 0, maxTokens)
	for i := 0; i < maxTokens && i < 10; i++ {
		idx := rand.Intn(len(keywords))
		result = append(result, keywords[idx])
	}
	return strings.Join(result, " ")
}

