package test

import (
	"bytes"
	"encoding/json"
	"fmt"
	"math"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

// ==================================================
// Phase I 테스트 스위트
// ==================================================

// ─────────────────────────────────────────────────
// 유닛 테스트: Top-K 샘플링
// ─────────────────────────────────────────────────

func TestTopKSampling(t *testing.T) {
	// logits: [0.1, 5.0, 0.2, 4.0, 0.3] → top2: idx 1, 3
	logits := []float64{0.1, 5.0, 0.2, 4.0, 0.3}

	// k=2, temperature=1.0 → 인덱스 1 또는 3이 선택되어야 함
	counts := map[int]int{}
	for i := 0; i < 100; i++ {
		idx := topKSampleTest(logits, 2, 1.0)
		counts[idx]++
	}

	// 인덱스 1과 3만 선택되어야 함
	for k := range counts {
		if k != 1 && k != 3 {
			t.Errorf("top-2에서 인덱스 %d가 선택됨 (1, 3만 가능)", k)
		}
	}
	t.Logf("Top-2 분포: %v", counts)
}

// 테스트용 top-k 구현 (패키지 독립)
func topKSampleTest(logits []float64, k int, temperature float64) int {
	n := len(logits)
	if k > n { k = n }

	scaled := make([]float64, n)
	for i, v := range logits {
		scaled[i] = v / temperature
	}

	// softmax
	maxV := scaled[0]
	for _, v := range scaled { if v > maxV { maxV = v } }
	sum := 0.0
	probs := make([]float64, n)
	for i, v := range scaled {
		probs[i] = math.Exp(v - maxV)
		sum += probs[i]
	}
	for i := range probs { probs[i] /= sum }

	// top-k 선택
	type iv struct{ i, _ int; v float64 }
	topK := make([]struct{ idx int; val float64 }, n)
	for i, v := range probs { topK[i] = struct{ idx int; val float64 }{i, v} }
	for i := 1; i < n; i++ {
		j := i
		for j > 0 && topK[j-1].val < topK[j].val {
			topK[j-1], topK[j] = topK[j], topK[j-1]
			j--
		}
	}

	total := 0.0
	for i := 0; i < k; i++ { total += topK[i].val }

	r := math.Mod(math.Abs(math.Sin(float64(k*17))), 1.0) * total
	cumul := 0.0
	for i := 0; i < k; i++ {
		cumul += topK[i].val
		if r <= cumul { return topK[i].idx }
	}
	return topK[0].idx
}

// ─────────────────────────────────────────────────
// 유닛 테스트: Perplexity 계산
// ─────────────────────────────────────────────────

func TestPerplexityRange(t *testing.T) {
	// PPL은 항상 >= 1
	ppl := math.Exp(5.0)
	if ppl < 1.0 {
		t.Errorf("PPL은 1 이상이어야 함: got %f", ppl)
	}

	// 낮은 loss → 낮은 PPL
	lowLoss := math.Exp(1.0)
	highLoss := math.Exp(10.0)
	if lowLoss >= highLoss {
		t.Errorf("낮은 loss PPL(%f) >= 높은 loss PPL(%f)", lowLoss, highLoss)
	}
	t.Logf("PPL range: low=%.2f, high=%.2f", lowLoss, highLoss)
}

// ─────────────────────────────────────────────────
// 유닛 테스트: 코퍼스 어휘 크기
// ─────────────────────────────────────────────────

func TestCorpusVocabSize(t *testing.T) {
	// 기본 특수 토큰 4개 + 실제 단어
	specialTokens := map[string]int{"<PAD>": 0, "<UNK>": 1, "<BOS>": 2, "<EOS>": 3}
	if len(specialTokens) != 4 {
		t.Errorf("특수 토큰은 4개여야 함: got %d", len(specialTokens))
	}

	// vocab 크기 제한: 최대 2004 (4 특수 + 2000 단어)
	maxVocab := 2004
	if maxVocab < 4 {
		t.Error("vocab 크기가 너무 작음")
	}
	t.Logf("최대 vocab 크기: %d", maxVocab)
}

// ─────────────────────────────────────────────────
// 유닛 테스트: 텍스트 생성 (API 함수)
// ─────────────────────────────────────────────────

func TestGeneratePhaseIAPI(t *testing.T) {
	tests := []struct {
		prompt  string
		maxToks int
	}{
		{"fn", 10},
		{"let", 5},
		{"//", 8},
		{"return", 5},
