// FreeLang v8 ML — GPT Tokenizer 예제 (Phase J)
//
// FL8 소스에서 tokenizer를 직접 사용하는 예제
// 실행: npx ts-node --transpile-only src/fl8.ts run examples/gpt_tokenize.fl8

print("=== Phase J: FL8 GPT Tokenizer 예제 ===")
print("")

// ─── 1. 인라인 vocab으로 tokenizer 생성 ──────────────────────
// tok_make에 [[token, id], ...] 배열 전달
let vocab_pairs = [
  ["<PAD>", 0], ["<UNK>", 1], ["<BOS>", 2], ["<EOS>", 3],
  ["fn", 4], ["let", 5], ["return", 6], ["if", 7],
  ["else", 8], ["for", 9], ["while", 10], ["in", 11],
  ["range", 12], ["->", 13], ["i32", 14], ["f32", 15],
  ["str", 16], ["print", 17], ["true", 18], ["false", 19],
  ["FreeLang", 20], ["GPT", 21], ["Phase", 22], ["ML", 23]
]

let tok = tok_make(vocab_pairs)

// ─── 2. vocab_size 확인 ──────────────────────────────────────
let vsize = tok_vocab_size(tok)
print("vocab_size:", vsize)

// ─── 3. 특수 토큰 id 확인 ────────────────────────────────────
let pad_id  = tok_special(tok, "pad")
let unk_id  = tok_special(tok, "unk")
let bos_id  = tok_special(tok, "bos")
let eos_id  = tok_special(tok, "eos")
print("special tokens: PAD=" + str(pad_id) + " UNK=" + str(unk_id) + " BOS=" + str(bos_id) + " EOS=" + str(eos_id))

// ─── 4. 인코딩 ───────────────────────────────────────────────
let src = "fn let return FreeLang GPT"
let ids = tok_encode(tok, src)
print("")
print("encode(\"" + src + "\") →", ids)

// ─── 5. 디코딩 ───────────────────────────────────────────────
let decoded = tok_decode(tok, ids)
print("decode →", decoded)

// ─── 6. 단일 token ↔ id ──────────────────────────────────────
let fn_id    = tok_id(tok, "fn")
let fn_token = tok_token(tok, fn_id)
print("")
print("tok_id(\"fn\") =", fn_id)
print("tok_token(" + str(fn_id) + ") =", fn_token)

// ─── 7. 미지 단어 → UNK ──────────────────────────────────────
let unk_word = "unknown_xyz"
let unk_encoded = tok_encode(tok, unk_word)
print("")
print("unknown 단어 encode:", unk_encoded, "→ UNK id =", unk_id)

// ─── 8. FreeLang 코드 스니펫 인코딩 ─────────────────────────
let code = "fn if else for while in range"
let code_ids = tok_encode(tok, code)
print("")
print("코드 encode:", code_ids)
let code_back = tok_decode(tok, code_ids)
print("코드 decode:", code_back)

print("")
print("=== 완료 ===")

