// FreeLang v8 ML — GPT Embedding (Phase K)
//
// token embedding + positional embedding
// 내장 함수: zeros(rows, cols), t_row, t_set_row, t_add, randn

// ─── embedding 행렬 초기화 ────────────────────────────────────
// make_embed(vocab_size, d_model) → [vocab_size, d_model] tensor

fn make_embed(vocab_size: i32, d_model: i32) -> i32 {
  return 0
}

// embed_lookup(table, token_id) → [d_model] 1D tensor
// table: [vocab_size, d_model]

fn embed_lookup(table: i32, token_id: i32) -> i32 {
  return t_row(table, token_id)
}

// embed_seq(table, ids) → [seq_len, d_model] 2D tensor
// ids: [id0, id1, ...] (FL8 배열)

fn embed_seq(table: i32, ids: i32, seq_len: i32, d_model: i32) -> i32 {
  let out = zeros(seq_len, d_model)
  let i = 0
  for i in range(seq_len) {
    let row = t_row(table, int(ids[i]))
    t_set_row(out, i, row)
  }
  return out
}

// pos_embed_sinusoidal(seq_len, d_model) → [seq_len, d_model]
// sin/cos positional encoding (고정값)

fn pos_embed_sinusoidal(seq_len: i32, d_model: i32) -> i32 {
  let pe = zeros(seq_len, d_model)
  let pos = 0
  for pos in range(seq_len) {
    let d = 0
    for d in range(d_model) {
      let exponent = d / d_model
      let denom = pow(10000.0, exponent)
      if d % 2 == 0 {
        let val = sin(pos / denom)
        tset(pe, pos, d, val)
      } else {
        let val = cos(pos / denom)
        tset(pe, pos, d, val)
      }
    }
  }
  return pe
}

// embed_forward(tok_table, pos_table, ids, seq_len, d_model)
//   → [seq_len, d_model]  token_embed + pos_embed

fn embed_forward(tok_table: i32, pos_table: i32, ids: i32, seq_len: i32, d_model: i32) -> i32 {
  let tok_e = embed_seq(tok_table, ids, seq_len, d_model)
  let pos_e = zeros(seq_len, d_model)
  let i = 0
  for i in range(seq_len) {
    let row = t_row(pos_table, i)
    t_set_row(pos_e, i, row)
  }
  return t_add(tok_e, pos_e)
}

// ─── 검증 ────────────────────────────────────────────────────

print("=== gpt_embedding.fl8 ===")

// 1) embed_lookup
let vocab_size = 10
let d_model = 4
let tok_table = randn(vocab_size, d_model)
let row0 = embed_lookup(tok_table, 0)
let row3 = embed_lookup(tok_table, 3)
print("embed_lookup shape:", shape(row0))

// 2) embed_seq
let ids = [2, 5, 1, 8]
let seq_len = 4
let tok_seq = embed_seq(tok_table, ids, seq_len, d_model)
print("embed_seq shape:", shape(tok_seq))

// 3) pos_embed_sinusoidal
let pos_e = pos_embed_sinusoidal(seq_len, d_model)
print("pos_embed shape:", shape(pos_e))

// 4) embed_forward
let pos_table = randn(seq_len, d_model)
let x = embed_forward(tok_table, pos_table, ids, seq_len, d_model)
print("embed_forward shape:", shape(x))

print("PASS: gpt_embedding.fl8")

