// embed_seq(table, ids) → [seq_len, d_model] 2D tensor
// ids: [id0, id1, ...] (FL8 배열)

fn embed_seq(table: i32, ids: i32, seq_len: i32, d_model: i32) -> i32 {
  let out = zeros(seq_len, d_model)
  let i = 0
  for i in range(seq_len) {
    let row = t_row(table, int(ids[i]))
    t_set_row(out, i, row)
  }
  return out
}

// pos_embed_sinusoidal(seq_len, d_model) → [seq_len, d_model]
// sin/cos positional encoding (고정값)

fn pos_embed_sinusoidal(seq_len: i32, d_model: i32) -> i32 {
  let pe = zeros(seq_len, d_model)
  let pos = 0
  for pos in range(seq_len) {
    let d = 0
    for d in range(d_model) {
      let exponent = d / d_model
      let denom = pow(10000.0, exponent)
      if d % 2 == 0 {
        let val = sin(pos / denom)
        tset(pe, pos, d, val)
      } else {
        let val = cos(pos / denom)
        tset(pe, pos, d, val)
      }
    }
  }
  return pe
}

// embed_forward(tok_table, pos_table, ids, seq_len, d_model)
//   → [seq_len, d_model]  token_embed + pos_embed

fn embed_forward(tok_table: i32, pos_table: i32, ids: i32, seq_len: i32, d_model: i32) -> i32 {
  let tok_e = embed_seq(tok_table, ids, seq_len, d_model)
  let pos_e = zeros(seq_len, d_model)
  let i = 0
  for i in range(seq_len) {
    let row = t_row(pos_table, i)
    t_set_row(pos_e, i, row)
  }
  return t_add(tok_e, pos_e)
}

