// FreeLang v8 ML — GPT Transformer Block (Phase K)
//
// Pre-LN 구조:
//   x → LN → Attention → x + attn_out   (residual)
//   x → LN → FFN       → x + ffn_out    (residual)
//
// FFN: Linear(d, 4d) → GELU → Linear(4d, d)

// ─── FFN ──────────────────────────────────────────────────────
// ffn_fwd(x, W1, b1, W2, b2, seq_len, d, ffn_dim)
//   → [seq_len, d]

fn ffn_fwd(x: i32, W1: i32, b1: i32, W2: i32, b2: i32,
           seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  // hidden = x @ W1 + b1  [seq, ffn_dim]
  let h = matmul(x, W1)
  let i = 0
  for i in range(seq_len) {
    let row = t_row(h, i)
    let new_row = t_add(row, b1)
    t_set_row(h, i, new_row)
  }
  // GELU
  let h_act = t_gelu(h)
  // out = h_act @ W2 + b2  [seq, d]
  let out = matmul(h_act, W2)
  for i in range(seq_len) {
    let row = t_row(out, i)
    let new_row = t_add(row, b2)
    t_set_row(out, i, new_row)
  }
  return out
}

// ─── LayerNorm (row-wise) ─────────────────────────────────────
// row_layer_norm(x, scale, bias, seq_len, d)
//   → [seq_len, d]

fn row_layer_norm(x: i32, scale: i32, bias: i32, seq_len: i32, d: i32) -> i32 {
  let out = zeros(seq_len, d)
  let i = 0
  for i in range(seq_len) {
    let row = t_row(x, i)
    let normed = t_layer_norm(row, scale, bias, 0.00001)
    t_set_row(out, i, normed)
  }
  return out
}

// ─── Transformer Block ────────────────────────────────────────
// block_fwd(x, Wq, Wk, Wv, Wo, bq, bk, bv, bo,
//           W1, b1, W2, b2,
//           ln1_scale, ln1_bias, ln2_scale, ln2_bias,
//           seq_len, d, ffn_dim)
//   → [seq_len, d]
//
// 참고: attn_fwd는 gpt_attention.fl8에 정의됨

fn block_fwd(x: i32,
             Wq: i32, Wk: i32, Wv: i32, Wo: i32,
             bq: i32, bk: i32, bv: i32, bo: i32,
             W1: i32, b1: i32, W2: i32, b2: i32,
             ln1_scale: i32, ln1_bias: i32,
             ln2_scale: i32, ln2_bias: i32,
             seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  // 1) Pre-LN → Attention → Residual
  let x1 = row_layer_norm(x, ln1_scale, ln1_bias, seq_len, d)
  let attn_out = attn_fwd(x1, Wq, Wk, Wv, Wo, bq, bk, bv, bo, seq_len, d)
  let x2 = t_add(x, attn_out)

  // 2) Pre-LN → FFN → Residual
  let x3 = row_layer_norm(x2, ln2_scale, ln2_bias, seq_len, d)
  let ffn_out = ffn_fwd(x3, W1, b1, W2, b2, seq_len, d, ffn_dim)
  let x4 = t_add(x2, ffn_out)

  return x4
}

