// FreeLang v8 ML — GPT Model Forward Pass (Phase K)
//
// 전체 파이프라인:
//   token_ids → embedding → N × block → final_ln → lm_head → logits
//
// 모델 파라미터를 배열로 묶어 관리
// (FL8는 struct/record 없으므로 배열 기반 파라미터 팩 사용)

// ─── 단일 레이어 forward (block + 파라미터 팩) ──────────────
// layer_fwd(x, params, layer_idx, seq_len, d, ffn_dim)
//   params: [Wq, Wk, Wv, Wo, bq, bk, bv, bo, W1, b1, W2, b2,
//            ln1s, ln1b, ln2s, ln2b]  (레이어당 16개)

fn layer_fwd(x: i32, params: i32, li: i32,
             seq_len: i32, d: i32, ffn_dim: i32) -> i32 {
  let base = li * 16
  let Wq = params[base + 0]
  let Wk = params[base + 1]
  let Wv = params[base + 2]
  let Wo = params[base + 3]
  let bq = params[base + 4]
  let bk = params[base + 5]
  let bv = params[base + 6]
  let bo = params[base + 7]
  let W1 = params[base + 8]
  let b1 = params[base + 9]
  let W2 = params[base + 10]
  let b2 = params[base + 11]
  let ln1s = params[base + 12]
  let ln1b = params[base + 13]
  let ln2s = params[base + 14]
  let ln2b = params[base + 15]
  return block_fwd(x,
    Wq, Wk, Wv, Wo, bq, bk, bv, bo,
    W1, b1, W2, b2,
    ln1s, ln1b, ln2s, ln2b,
    seq_len, d, ffn_dim)
}

// ─── make_layer_params(d, ffn_dim) → 16개 파라미터 배열 ─────

fn make_layer_params(d: i32, ffn_dim: i32) -> i32 {
  let params = []
  // Wq, Wk, Wv, Wo: [d, d]
  push(params, randn(d, d))
  push(params, randn(d, d))
  push(params, randn(d, d))
  push(params, randn(d, d))
  // bq, bk, bv, bo: [d] (1D)
  push(params, reshape(zeros(d), d))
  push(params, reshape(zeros(d), d))
  push(params, reshape(zeros(d), d))
  push(params, reshape(zeros(d), d))
  // W1: [d, ffn_dim], b1: [ffn_dim]
  push(params, randn(d, ffn_dim))
  push(params, reshape(zeros(ffn_dim), ffn_dim))
  // W2: [ffn_dim, d], b2: [d]
  push(params, randn(ffn_dim, d))
  push(params, reshape(zeros(d), d))
  // ln1_scale, ln1_bias, ln2_scale, ln2_bias: [d] 1D
  push(params, reshape(ones(d), d))
  push(params, reshape(zeros(d), d))
  push(params, reshape(ones(d), d))
  push(params, reshape(zeros(d), d))
  return params
}

// ─── GPT forward ─────────────────────────────────────────────
// gpt_forward(tok_table, pos_table, all_params,
//             final_ln_scale, final_ln_bias, lm_head, lm_bias,
//             ids, num_layers, seq_len, d, ffn_dim, vocab_size)
//   → logits [vocab_size] (마지막 토큰의 logits)

fn gpt_forward(tok_table: i32, pos_table: i32, all_params: i32,
               final_ln_scale: i32, final_ln_bias: i32,
               lm_head: i32, lm_bias: i32,
               ids: i32, num_layers: i32,
               seq_len: i32, d: i32, ffn_dim: i32, vocab_size: i32) -> i32 {
  // 1) Embedding
  let x = embed_forward(tok_table, pos_table, ids, seq_len, d)

  // 2) N × Transformer block
  let li = 0
  for li in range(num_layers) {
    x = layer_fwd(x, all_params, li, seq_len, d, ffn_dim)
  }

  // 3) Final LayerNorm (마지막 토큰 행만)
  let last_row = t_row(x, seq_len - 1)
  let ln_out = t_layer_norm(last_row, final_ln_scale, final_ln_bias, 0.00001)

  // 4) LM head: [d] @ [d, vocab] → [vocab]
  // lm_head: [d, vocab_size]
  let ln_2d = reshape(ln_out, 1, d)
  let logits_2d = matmul(ln_2d, lm_head)
  let logits = t_row(logits_2d, 0)

  // 5) bias 추가
  let logits_b = t_add(logits, lm_bias)
  return logits_b
}

// ─── make_gpt_model ──────────────────────────────────────────
// 전체 모델 파라미터를 하나의 배열로 반환
// [tok_table, pos_table, [layer_params...],
//  final_ln_scale, final_ln_bias, lm_head, lm_bias]

fn make_gpt_model(vocab_size: i32, d: i32, ffn_dim: i32,
                  num_layers: i32, max_seq_len: i32) -> i32 {
  let model = []
  // tok_table: [vocab_size, d]
  push(model, randn(vocab_size, d))
  // pos_table: [max_seq_len, d]
  push(model, randn(max_seq_len, d))
  // layer params
  let all_params = []
  let li = 0
  for li in range(num_layers) {
    let lp = make_layer_params(d, ffn_dim)
    let pi = 0
    for pi in range(16) {
      push(all_params, lp[pi])
    }
  }
  push(model, all_params)
  // final LN
  push(model, reshape(ones(d), d))
  push(model, reshape(zeros(d), d))
  // lm_head: [d, vocab_size], lm_bias: [vocab_size]
  push(model, randn(d, vocab_size))
  push(model, reshape(zeros(vocab_size), vocab_size))
  return model
}

// ─── model_forward 래퍼 ──────────────────────────────────────
fn model_forward(model: i32, ids: i32,
                 num_layers: i32, seq_len: i32,
                 d: i32, ffn_dim: i32, vocab_size: i32) -> i32 {
  let tok_table     = model[0]
  let pos_table     = model[1]
  let all_params    = model[2]
  let final_ln_scale = model[3]
  let final_ln_bias  = model[4]
  let lm_head       = model[5]
  let lm_bias       = model[6]
  return gpt_forward(tok_table, pos_table, all_params,
                     final_ln_scale, final_ln_bias, lm_head, lm_bias,
                     ids, num_layers, seq_len, d, ffn_dim, vocab_size)
}

// ─── 검증 ────────────────────────────────────────────────────

print("=== gpt_model.fl8 ===")

let vocab_size = 20
let d = 8
let ffn_dim = 16
let num_layers = 2
let max_seq = 8
let seq_len = 4

// 모델 생성
let model = make_gpt_model(vocab_size, d, ffn_dim, num_layers, max_seq)
print("model 파라미터 수:", len(model))

// 입력: 랜덤 token ids
let ids = [3, 7, 1, 5]

// Forward
let logits = model_forward(model, ids, num_layers, seq_len, d, ffn_dim, vocab_size)
print("logits shape:", shape(logits))
print("logits length:", len(shape(logits)))

// argmax → 예측 토큰
let pred = t_argmax(logits)
print("predicted next token:", pred)

// softmax 확률
let probs = t_softmax(logits)
print("probs sum:", t_sum(probs))

print("PASS: gpt_model.fl8")

